var doc = Document;
// Goal: change the model so a mistake rolls back and a success is one undo step.
// The connector holds a transaction GROUP open for the whole run and NO transaction:
// the document is readable at top level but not modifiable until a
// Connector.WithTransaction block opens one (skill.md "Writing to a document").

// 1. Reads need no block. IsModifiable is false here: a write at this point throws
//    Autodesk.Revit.Exceptions.ModificationOutsideTransactionException, which the
//    connector reports as `script-write-outside-transaction` (not demonstrated: the
//    run would fail). Everything that writes goes inside a block.
bool modifiableAtTopLevel = doc.IsModifiable;
int levelsBefore = new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfClass(typeof(Autodesk.Revit.DB.Level)).GetElementCount();

// 2. The value-returning form: WithTransaction<T>(doc, Func<T>) hands the body's
//    result back. Batch related writes in ONE block; each block is one commit and
//    one undo step. Inside the block IsModifiable is true.
var kept = Connector.WithTransaction(doc, () => {
  var lvl = Autodesk.Revit.DB.Level.Create(doc, 101.0);
  lvl.Name = "How-to L101";
  return new { id = lvl.Id.Value, modifiableInside = doc.IsModifiable };
});

// 3. A body that throws is ROLLED BACK even when the script catches the exception:
//    the level at 102.0 never exists after this, and the document stays usable
//    for the next block. This is the ordinary "try an API, fall back" shape.
bool caught = false;
try {
  Connector.WithTransaction(doc, () => {
    Autodesk.Revit.DB.Level.Create(doc, 102.0);
    throw new System.InvalidOperationException("deliberate: abandon this batch");
  });
} catch (System.InvalidOperationException) {
  caught = true;
}

// 4. A savepoint INSIDE a block: a native SubTransaction, always in a `using`.
//    RollBack discards exactly its own slice; Commit keeps it; writes outside the
//    savepoint are untouched either way. Started with no block open it is refused
//    with `script-subtransaction-needs-transaction`. Dispose alone (no Commit) rolls
//    back -- never leave one un-disposed.
var savepoint = Connector.WithTransaction(doc, () => {
  Autodesk.Revit.DB.Level.Create(doc, 103.0);
  using (var st = new Autodesk.Revit.DB.SubTransaction(doc)) {
    st.Start();
    Autodesk.Revit.DB.Level.Create(doc, 104.0);   // discarded below
    st.RollBack();
  }
  using (var st = new Autodesk.Revit.DB.SubTransaction(doc)) {
    st.Start();
    Autodesk.Revit.DB.Level.Create(doc, 105.0);   // kept
    st.Commit();
  }
  return "savepoint-demo";
});

// 5. Verify at top level: count what survived by elevation. Expected: 101, 103 and
//    105 exist; 102 (thrown block) and 104 (rolled-back savepoint) do not. The run's
//    `mutations` report says the same: net_created 3 under Levels.
var survivors = new System.Collections.Generic.Dictionary<string, int>();
foreach (var e in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  var lvl = e as Autodesk.Revit.DB.Level;
  if (lvl == null) continue;
  foreach (var probe in new[] { 101.0, 102.0, 103.0, 104.0, 105.0 }) {
    if (System.Math.Abs(lvl.Elevation - probe) < 0.01) survivors[probe.ToString()] = survivors.TryGetValue(probe.ToString(), out var n) ? n + 1 : 1;
  }
}
// 6. Return a projection, never an Element (see results-return-values-and-mutations).
return new {
  modifiableAtTopLevel,            // false
  keptLevelId = kept.id,
  modifiableInsideBlock = kept.modifiableInside, // true
  throwWasCaught = caught,         // true, and its level is gone
  savepoint,
  levelsAtStart = levelsBefore,
  survivors                        // {"101":1,"103":1,"105":1}
};
